def state_abstraction(grid):
    # Define valid movements (cardinal directions)
    movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Initialize groups dictionary to keep track of connected states
    groups = {}

    # Iterate over all cells in the grid
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] != "X":  # Ignore obstacle cells
                group_id = None

                # Check adjacent cells
                for movement in movements:
                    new_i, new_j = i + movement[0], j + movement[1]
                    if 0 <= new_i < len(grid) and 0 <= new_j < len(grid[new_i]) and grid[new_i][new_j] != "X":
                        # If adjacent cell is already assigned to a group, assign it to the same group
                        if (new_i, new_j) in groups:
                            group_id = groups[(new_i, new_j)]
                            break

                # If no adjacent cells are connected, create a new group
                if group_id is None:
                    group_id = len(groups)
                    groups[(i, j)] = group_id

    return list(groups.values())


